'use strict';const a403_0x3cbc5f=a403_0x5720;(function(_0x175814,_0x16e5af){const _0x5c740a=a403_0x5720,_0x1da22e=_0x175814();while(!![]){try{const _0x2d3559=parseInt(_0x5c740a(0xa1))/0x1+parseInt(_0x5c740a(0xa0))/0x2+parseInt(_0x5c740a(0xa3))/0x3*(-parseInt(_0x5c740a(0xa6))/0x4)+parseInt(_0x5c740a(0xaa))/0x5+-parseInt(_0x5c740a(0xa4))/0x6*(-parseInt(_0x5c740a(0xa7))/0x7)+parseInt(_0x5c740a(0xa2))/0x8+parseInt(_0x5c740a(0xa5))/0x9*(-parseInt(_0x5c740a(0xa8))/0xa);if(_0x2d3559===_0x16e5af)break;else _0x1da22e['push'](_0x1da22e['shift']());}catch(_0x43f589){_0x1da22e['push'](_0x1da22e['shift']());}}}(a403_0x146b,0xe2940));function a403_0x5720(_0x1daf3a,_0x22f372){_0x1daf3a=_0x1daf3a-0xa0;const _0x146b5d=a403_0x146b();let _0x5720b0=_0x146b5d[_0x1daf3a];if(a403_0x5720['iiQiaO']===undefined){var _0x4d99dc=function(_0x45e7d6){const _0x59bcff='abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+/=';let _0x5cc357='',_0x5a153b='';for(let _0x1fb37c=0x0,_0x5dfb96,_0x4c03ac,_0x518834=0x0;_0x4c03ac=_0x45e7d6['charAt'](_0x518834++);~_0x4c03ac&&(_0x5dfb96=_0x1fb37c%0x4?_0x5dfb96*0x40+_0x4c03ac:_0x4c03ac,_0x1fb37c++%0x4)?_0x5cc357+=String['fromCharCode'](0xff&_0x5dfb96>>(-0x2*_0x1fb37c&0x6)):0x0){_0x4c03ac=_0x59bcff['indexOf'](_0x4c03ac);}for(let _0x3e3c6b=0x0,_0x5600bd=_0x5cc357['length'];_0x3e3c6b<_0x5600bd;_0x3e3c6b++){_0x5a153b+='%'+('00'+_0x5cc357['charCodeAt'](_0x3e3c6b)['toString'](0x10))['slice'](-0x2);}return decodeURIComponent(_0x5a153b);};a403_0x5720['vGCbEU']=_0x4d99dc,a403_0x5720['atvRIC']={},a403_0x5720['iiQiaO']=!![];}const _0x5264a2=_0x146b5d[0x0],_0x3d4053=_0x1daf3a+_0x5264a2,_0xd1cd43=a403_0x5720['atvRIC'][_0x3d4053];return!_0xd1cd43?(_0x5720b0=a403_0x5720['vGCbEU'](_0x5720b0),a403_0x5720['atvRIC'][_0x3d4053]=_0x5720b0):_0x5720b0=_0xd1cd43,_0x5720b0;}function a403_0x146b(){const _0x29ccb1=['mZyWotaYn29cvfDWvq','nda0ngnqEvbhsa','ndiZCevjAejw','nfb5BKLtqW','mtu1odL3AfLMs04','mtKYmZeWuvvWCLbI','D2vICgfJA0nODw5RD2vIx3rVB2XFDNvL','otiYotv5q0L2t2u','mtuXmdCYnermyvvoqq','mZi4nZGXEMjYtKze','mZq1mdy0mhfgvxPYzG'];a403_0x146b=function(){return _0x29ccb1;};return a403_0x146b();}(self['webpackChunkweb_tool_vue']=self[a403_0x3cbc5f(0xa9)]||[])['push']([[0x2565],{0x2565:function(_0x4da012,_0x1473dd){const _0x174d03='\x0a<div\x20class=\x22text-gray-800\x20bg-white\x22>\x0a\x20\x20<article\x20class=\x22max-w-4xl\x20mx-auto\x20px-4\x20py-8\x20md:px-6\x22>\x0a\x20\x20\x20\x20<h1\x20class=\x22text-3xl\x20md:text-4xl\x20font-bold\x20mb-6\x20text-gray-900\x22>屏幕录制其实很简单：一文看懂怎么录屏和常用设置</h1>\x0a\x20\x20\x20\x20\x0a\x20\x20\x20\x20<p\x20class=\x22mb-6\x20text-lg\x20leading-relaxed\x22>\x0a\x20\x20\x20\x20\x20\x20你有没有遇到过这样的情景？想保存一段重要的线上会议内容，或是给朋友演示软件怎么操作，又或者想记录下自己打游戏的精彩瞬间，却不知道该怎么把电脑屏幕上的画面录下来。\x0a\x20\x20\x20\x20</p>\x0a\x20\x20\x20\x20\x0a\x20\x20\x20\x20<p\x20class=\x22mb-8\x20text-lg\x20leading-relaxed\x22>\x0a\x20\x20\x20\x20\x20\x20别担心，屏幕录制这件事，远没有你想的那么复杂。今天我们就来聊聊，如何轻松地录制屏幕视频，以及那些听起来很专业的设置，到底该怎么选。\x0a\x20\x20\x20\x20</p>\x0a\x0a\x20\x20\x20\x20<div\x20class=\x22bg-blue-50\x20border-l-4\x20border-blue-500\x20p-4\x20mb-8\x20rounded-r\x22>\x0a\x20\x20\x20\x20\x20\x20<p\x20class=\x22text-gray-700\x22>\x0a\x20\x20\x20\x20\x20\x20\x20\x20本文不涉及任何复杂的技术术语，就像朋友聊天一样，告诉你录屏的常识和技巧。\x0a\x20\x20\x20\x20\x20\x20</p>\x0a\x20\x20\x20\x20</div>\x0a\x0a\x20\x20\x20\x20<h2\x20class=\x22text-2xl\x20md:text-3xl\x20font-semibold\x20mt-10\x20mb-4\x20text-gray-900\x20pb-2\x20border-b\x22>录屏能用来做什么？比你想象的更多</h2>\x0a\x20\x20\x20\x20<p\x20class=\x22mb-4\x22>\x0a\x20\x20\x20\x20\x20\x20很多人觉得录屏是专业人士才用的功能，其实不然。它在我们的日常工作和生活中非常实用：\x0a\x20\x20\x20\x20</p>\x0a\x20\x20\x20\x20<ul\x20class=\x22list-disc\x20pl-5\x20mb-8\x20space-y-2\x22>\x0a\x20\x20\x20\x20\x20\x20<li><strong>工作学习：</strong>保存重要的培训会议、制作软件操作教程、记录网课重点内容。</li>\x0a\x20\x20\x20\x20\x20\x20<li><strong>生活娱乐：</strong>录制游戏高光时刻、保存线上家人的视频聊天、记录直播中有趣的片段。</li>\x0a\x20\x20\x20\x20\x20\x20<li><strong>沟通协助：</strong>当用语言说不清电脑问题时，直接录一段视频发给别人看，一目了然。</li>\x0a\x20\x20\x20\x20</ul>\x0a\x0a\x20\x20\x20\x20<h2\x20class=\x22text-2xl\x20md:text-3xl\x20font-semibold\x20mt-10\x20mb-4\x20text-gray-900\x20pb-2\x20border-b\x22>录制前，需要了解的几项简单设置</h2>\x0a\x20\x20\x20\x20<p\x20class=\x22mb-6\x22>\x0a\x20\x20\x20\x20\x20\x20开始录制前，你可能会看到几个选项。别被它们吓到，我们一个一个说清楚。\x0a\x20\x20\x20\x20</p>\x0a\x0a\x20\x20\x20\x20<h3\x20class=\x22text-xl\x20font-medium\x20mt-6\x20mb-3\x20text-gray-800\x22>1.\x20清晰度（分辨率）：选适合的，不一定要最高的</h3>\x0a\x20\x20\x20\x20<p\x20class=\x22mb-4\x22>\x0a\x20\x20\x20\x20\x20\x20就像电视有标清、高清一样，录屏也有清晰度选择。\x0a\x20\x20\x20\x20</p>\x0a\x20\x20\x20\x20<ul\x20class=\x22list-disc\x20pl-5\x20mb-6\x20space-y-2\x22>\x0a\x20\x20\x20\x20\x20\x20<li><strong>1080P：</strong>最清晰的选项，适合录制细节丰富的画面，比如设计软件操作、高清游戏。文件会比较大。</li>\x0a\x20\x20\x20\x20\x20\x20<li><strong>720P：</strong>高清画质，适合大多数情况，比如录制会议、网页操作。清晰度和文件大小比较平衡，最常用。</li>\x0a\x20\x20\x20\x20\x20\x20<li><strong>480P：</strong>普通画质，如果对清晰度要求不高，或者想快速分享一个小文件，可以选择它。</li>\x0a\x20\x20\x20\x20</ul>\x0a\x20\x20\x20\x20<p\x20class=\x22mb-8\x20text-gray-600\x22>\x0a\x20\x20\x20\x20\x20\x20简单来说，日常使用选720P就很好。如果录给手机看，480P也足够清晰。\x0a\x20\x20\x20\x20</p>\x0a\x0a\x20\x20\x20\x20<h3\x20class=\x22text-xl\x20font-medium\x20mt-6\x20mb-3\x20text-gray-800\x22>2.\x20画面比例：视频形状的长和宽</h3>\x0a\x20\x20\x20\x20<p\x20class=\x22mb-4\x22>\x0a\x20\x20\x20\x20\x20\x20这个决定了你录出来的视频是“长方形”还是“正方形”。\x0a\x20\x20\x20\x20</p>\x0a\x20\x20\x20\x20<ul\x20class=\x22list-disc\x20pl-5\x20mb-6\x20space-y-2\x22>\x0a\x20\x20\x20\x20\x20\x20<li><strong>16:9：</strong>最常见的宽屏比例，和大多数电脑显示器、电视机、手机屏幕形状一样。录制通用视频就选它。</li>\x0a\x20\x20\x20\x20\x20\x20<li><strong>4:3：</strong>稍微“方”一点的比例，一些老式显示屏或特定演示文稿会用到。</li>\x0a\x20\x20\x20\x20\x20\x20<li><strong>1:1：</strong>正方形，适合录制一些用于社交媒体（如部分平台头像、短内容）的画面。</li>\x0a\x20\x20\x20\x20</ul>\x0a\x20\x20\x20\x20<p\x20class=\x22mb-8\x20text-gray-600\x22>\x0a\x20\x20\x20\x20\x20\x20不确定怎么选？直接选16:9，基本不会出错。\x0a\x20\x20\x20\x20</p>\x0a\x0a\x20\x20\x20\x20<h3\x20class=\x22text-xl\x20font-medium\x20mt-6\x20mb-3\x20text-gray-800\x22>3.\x20流畅度（帧率）：画面卡不卡的关键</h3>\x0a\x20\x20\x20\x20<p\x20class=\x22mb-4\x22>\x0a\x20\x20\x20\x20\x20\x20帧率可以理解为1秒钟闪过多少张画面。数字越高，视频看起来就越流畅。\x0a\x20\x20\x20\x20</p>\x0a\x20\x20\x20\x20<ul\x20class=\x22list-disc\x20pl-5\x20mb-6\x20space-y-2\x22>\x0a\x20\x20\x20\x20\x20\x20<li><strong>60\x20FPS：</strong>非常流畅，适合录制快速变化的画面，比如动作类游戏、体育赛事视频。</li>\x0a\x20\x20\x20\x20\x20\x20<li><strong>30\x20FPS：</strong>标准流畅度，适合录制办公软件操作、网页浏览、大部分会议和课程。这是最通用的选择。</li>\x0a\x20\x20\x20\x20\x20\x20<li><strong>15\x20FPS：</strong>基本流畅，如果只是录制一些几乎静止的画面（比如一张PPT停留很久），为了节省文件空间可以考虑。</li>\x0a\x20\x20\x20\x20</ul>\x0a\x20\x20\x20\x20<p\x20class=\x22mb-8\x20text-gray-600\x22>\x0a\x20\x20\x20\x20\x20\x20录制普通操作选30就够用。如果录游戏，可以试试60，观感会更好。\x0a\x20\x20\x20\x20</p>\x0a\x0a\x20\x20\x20\x20<h3\x20class=\x22text-xl\x20font-medium\x20mt-6\x20mb-3\x20text-gray-800\x22>4.\x20视频格式和一个小细节</h3>\x0a\x20\x20\x20\x20<p\x20class=\x22mb-4\x22>\x0a\x20\x20\x20\x20\x20\x20<strong>视频格式：</strong>简单理解为视频的“包装盒”。常见的有MP4和WebM。MP4兼容性最好，几乎所有电脑和手机都能直接打开播放，建议优先选择。WebM在某些情况下文件更小。\x0a\x20\x20\x20\x20</p>\x0a\x20\x20\x20\x20<p\x20class=\x22mb-8\x22>\x0a\x20\x20\x20\x20\x20\x20<strong>显示光标：</strong>这个选项打勾后，录制时会把你鼠标指针（那个小箭头）也录进去。这在制作教学视频时非常有用，别人可以清楚看到你点了哪里。如果只是录制电影或游戏画面，可以关掉。\x0a\x20\x20\x20\x20</p>\x0a\x0a\x20\x20\x20\x20<h2\x20class=\x22text-2xl\x20md:text-3xl\x20font-semibold\x20mt-10\x20mb-4\x20text-gray-900\x20pb-2\x20border-b\x22>轻松三步，开始你的第一次录屏</h2>\x0a\x20\x20\x20\x20<ol\x20class=\x22list-decimal\x20pl-5\x20mb-8\x20space-y-4\x22>\x0a\x20\x20\x20\x20\x20\x20<li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<strong>第一步：选好设置。</strong>根据上面介绍的，结合你的用途，选好清晰度、比例等。第一次可以用推荐的组合：720P、16:9、30帧、MP4格式、勾选显示光标。\x0a\x20\x20\x20\x20\x20\x20</li>\x0a\x20\x20\x20\x20\x20\x20<li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<strong>第二步：开始录制。</strong>点击“开始录制”按钮。这时，你的电脑通常会让你选择“要录制整个屏幕，还是只录制某个软件窗口”。根据你的需要选择即可。\x0a\x20\x20\x20\x20\x20\x20</li>\x0a\x20\x20\x20\x20\x20\x20<li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<strong>第三步：结束与保存。</strong>录制完成后，点击“停止录制”。视频会自动保存到录制记录列表里。你可以播放预览，也可以点击“下载”把视频文件保存到自己的电脑中。\x0a\x20\x20\x20\x20\x20\x20</li>\x0a\x20\x20\x20\x20</ol>\x0a\x0a\x20\x20\x20\x20<div\x20class=\x22bg-gray-50\x20p-6\x20rounded-lg\x20border\x20border-gray-200\x20mb-10\x22>\x0a\x20\x20\x20\x20\x20\x20<h3\x20class=\x22text-xl\x20font-medium\x20mb-3\x20text-gray-900\x22>几个实用小贴士</h3>\x0a\x20\x20\x20\x20\x20\x20<ul\x20class=\x22space-y-2\x22>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<li\x20class=\x22flex\x20items-start\x22><span\x20class=\x22inline-block\x20h-2\x20w-2\x20bg-gray-600\x20rounded-full\x20mt-2\x20mr-3\x20flex-shrink-0\x22></span>\x20<span>录制前，关闭不必要的网页和软件通知，避免隐私信息或弹窗被录进去。</span></li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<li\x20class=\x22flex\x20items-start\x22><span\x20class=\x22inline-block\x20h-2\x20w-2\x20bg-gray-600\x20rounded-full\x20mt-2\x20mr-3\x20flex-shrink-0\x22></span>\x20<span>如果需要录音（比如讲解），记得在开始录制时，同意浏览器使用麦克风的请求。</span></li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<li\x20class=\x22flex\x20items-start\x22><span\x20class=\x22inline-block\x20h-2\x20w-2\x20bg-gray-600\x20rounded-full\x20mt-2\x20mr-3\x20flex-shrink-0\x22></span>\x20<span>录好的视频如果不需要了，记得在列表里“删除”，可以帮电脑节省空间。</span></li>\x0a\x20\x20\x20\x20\x20\x20</ul>\x0a\x20\x20\x20\x20</div>\x0a\x0a\x20\x20\x20\x20<h2\x20class=\x22text-2xl\x20md:text-3xl\x20font-semibold\x20mt-10\x20mb-4\x20text-gray-900\x20pb-2\x20border-b\x22>总结</h2>\x0a\x20\x20\x20\x20<p\x20class=\x22mb-4\x22>\x0a\x20\x20\x20\x20\x20\x20屏幕录制并不是一项专业技能，它只是一个方便我们保存和分享视觉信息的工具。\x0a\x20\x20\x20\x20</p>\x0a\x20\x20\x20\x20<p\x20class=\x22mb-4\x22>\x0a\x20\x20\x20\x20\x20\x20记住核心要点：<strong>日常使用，720P、30帧、MP4格式就是黄金组合</strong>。其他设置可以根据特殊需求稍作调整。\x0a\x20\x20\x20\x20</p>\x0a\x20\x20\x20\x20<p\x20class=\x22mb-10\x20text-lg\x22>\x0a\x20\x20\x20\x20\x20\x20希望这篇文章能帮你打消对录屏的陌生感。下次再需要保存屏幕上的精彩内容时，不妨轻松地试一试吧。\x0a\x20\x20\x20\x20</p>\x0a\x20\x20</article>\x0a</div>\x0a';_0x1473dd['default']=_0x174d03;}}]);